"""Public Python SDK for the run_eval pipeline."""

from __future__ import annotations

import json
import os
import signal
import subprocess
import sys
import tempfile
import threading
from codecs import getincrementaldecoder
from collections import deque
from collections.abc import Mapping
from pathlib import Path
from typing import BinaryIO

_PATH_CONFIG_KEYS = frozenset(
    {"input", "baseline_input", "reference_dir", "output", "checkpoint_dir"}
)
_REFERENCE_FILENAMES = (
    "reference.py",
    "input.py",
    "shapes.json",
    "metadata.json",
)
_EVAL_MODE_CANDIDATE = "candidate"
_EVAL_MODE_ABBA = "abba"
_EVAL_MODE_TORCH_COMPILE = "torch_compile_reference"
_EVAL_MODES = frozenset(
    {_EVAL_MODE_ABBA, _EVAL_MODE_CANDIDATE, _EVAL_MODE_TORCH_COMPILE}
)
_SDK_PROCESS_SHUTDOWN_TIMEOUT_S = 5.0
_SDK_STDERR_TAIL_LINES = 50
_SDK_STDERR_CHUNK_BYTES = 64 * 1024
_SDK_STDERR_PARTIAL_LINE_CHARS = 64 * 1024


class AtrexSDKError(Exception):
    """Base class for Python SDK failures without an eval result."""


class AtrexConfigError(AtrexSDKError, ValueError):
    """Raised when an SDK config cannot start a valid evaluation."""


class AtrexEvaluationError(AtrexSDKError, RuntimeError):
    """Raised when the evaluation process cannot produce a result payload."""


def evaluate(config: Mapping[str, object]) -> dict[str, object]:
    """Run one evaluation and return its ``eval_result.json`` payload."""

    normalized = _normalize_config(config)
    _validate_launch_paths(normalized)
    return _run_evaluation_process(normalized)


def _normalize_config(config: Mapping[str, object]) -> dict[str, object]:
    if not isinstance(config, Mapping):
        raise AtrexConfigError("config must be a Mapping[str, object]")
    try:
        normalized = dict(config)
    except Exception as error:
        raise AtrexConfigError(f"failed to read config Mapping: {error}") from error
    if any(not isinstance(key, str) for key in normalized):
        raise AtrexConfigError("config keys must be strings")

    for name in _PATH_CONFIG_KEYS.intersection(normalized):
        value = normalized[name]
        if value is None:
            continue
        if isinstance(value, os.PathLike):
            value = os.fspath(value)
        if not isinstance(value, str) or not value.strip():
            raise AtrexConfigError(
                f"{name} must be a non-empty path string or null"
            )
        # Launch paths belong to the caller's cwd, not a worker's package cwd.
        # Relative checkpoints deliberately remain relative to the run artifact.
        normalized[name] = value if name == "checkpoint_dir" else str(Path(value).resolve())

    try:
        json.dumps(normalized, allow_nan=False)
    except (TypeError, ValueError) as error:
        raise AtrexConfigError(
            f"config values must be JSON-compatible: {error}"
        ) from error
    return normalized


def _validate_launch_paths(config: Mapping[str, object]) -> None:
    default_eval_mode = (
        _EVAL_MODE_ABBA
        if config.get("baseline_input") is not None
        else _EVAL_MODE_CANDIDATE
    )
    eval_mode = config.get("eval_mode", default_eval_mode)
    if not isinstance(eval_mode, str) or eval_mode not in _EVAL_MODES:
        allowed = ", ".join(sorted(_EVAL_MODES))
        raise AtrexConfigError(f"eval_mode must be one of: {allowed}")

    reference_dir = _required_path(config, "reference_dir")
    if not reference_dir.is_dir():
        raise AtrexConfigError(f"reference_dir does not exist: {reference_dir}")
    missing = [
        filename
        for filename in _REFERENCE_FILENAMES
        if not (reference_dir / filename).is_file()
    ]
    if missing:
        raise AtrexConfigError(
            "reference_dir is missing required file(s): " + ", ".join(missing)
        )

    output = _required_path(config, "output")
    if output.exists() and not output.is_dir():
        raise AtrexConfigError(f"output must be a directory path: {output}")
    output_parent = _nearest_existing_parent(output)
    if not output_parent.is_dir() or not os.access(
        output_parent,
        os.W_OK | os.X_OK,
    ):
        raise AtrexConfigError(
            f"output parent is not writable: {output_parent}"
        )

    checkpoint = _optional_path(config, "checkpoint_dir")
    if (
        checkpoint is not None
        and checkpoint.is_absolute()
        and checkpoint.exists()
        and not checkpoint.is_dir()
    ):
        raise AtrexConfigError(
            f"checkpoint_dir must be a directory path: {checkpoint}"
        )

    input_path = _optional_path(config, "input")
    baseline_path = _optional_path(config, "baseline_input")
    if eval_mode == _EVAL_MODE_TORCH_COMPILE:
        if input_path is not None:
            raise AtrexConfigError(
                "input cannot be set for eval_mode=torch_compile_reference"
            )
        if baseline_path is not None:
            raise AtrexConfigError(
                "baseline_input cannot be set for eval_mode=torch_compile_reference"
            )
        return
    if input_path is None:
        raise AtrexConfigError(f"input is required for eval_mode={eval_mode}")
    _validate_candidate_file(input_path, "input")
    if eval_mode == _EVAL_MODE_ABBA:
        if baseline_path is None:
            raise AtrexConfigError("baseline_input is required for eval_mode=abba")
        _validate_candidate_file(baseline_path, "baseline_input")
        validation_mode = config.get("validation_mode", "full")
        if validation_mode != "full":
            raise AtrexConfigError("eval_mode=abba requires validation_mode=full")
    elif baseline_path is not None:
        raise AtrexConfigError("baseline_input requires eval_mode=abba")


def _validate_candidate_file(path: Path, name: str) -> None:
    if not path.is_file():
        raise AtrexConfigError(f"{name} does not exist: {path}")
    if path.suffix != ".py":
        raise AtrexConfigError(f"{name} must be a Python file: {path}")


def _required_path(config: Mapping[str, object], name: str) -> Path:
    value = config.get(name)
    if not isinstance(value, str) or not value.strip():
        raise AtrexConfigError(f"{name} must be a non-empty path string")
    return Path(value)


def _optional_path(config: Mapping[str, object], name: str) -> Path | None:
    value = config.get(name)
    if value is None:
        return None
    if not isinstance(value, str) or not value.strip():
        raise AtrexConfigError(f"{name} must be a non-empty path string or null")
    return Path(value)


def _nearest_existing_parent(path: Path) -> Path:
    current = path
    while not current.exists() and current != current.parent:
        current = current.parent
    return current


def _run_evaluation_process(config: Mapping[str, object]) -> dict[str, object]:
    output_root = _required_path(config, "output").resolve()
    with tempfile.TemporaryDirectory(prefix="atrex-bench-sdk-") as temporary_dir:
        temporary_root = Path(temporary_dir)
        config_path = temporary_root / "run_eval.json"
        pointer_path = temporary_root / "eval_result_path.txt"
        _write_private_config(config, config_path)
        command = [
            sys.executable,
            "-m",
            "atrex_bench.cli.run_eval",
            "--config",
            str(config_path),
            "--sdk-result-path-output",
            str(pointer_path),
        ]
        process = _start_process(command)
        if process.stderr is None:
            _stop_process(process)
            raise AtrexEvaluationError(
                "run_eval process did not expose a stderr stream"
            )
        stderr_tail: deque[str] = deque(maxlen=_SDK_STDERR_TAIL_LINES)
        reader_errors: list[OSError] = []
        stderr_reader = threading.Thread(
            target=_stream_stderr,
            args=(process.stderr, stderr_tail, reader_errors),
            name="atrex-sdk-stderr",
            daemon=True,
        )
        stderr_reader.start()
        try:
            returncode = process.wait()
        except BaseException:
            _stop_process(process)
            raise
        finally:
            stderr_reader.join(timeout=_SDK_PROCESS_SHUTDOWN_TIMEOUT_S)
            process.stderr.close()

        if stderr_reader.is_alive():
            raise AtrexEvaluationError(
                "run_eval stderr reader did not stop after process exit"
            )
        if reader_errors:
            raise AtrexEvaluationError(
                f"failed to read run_eval stderr: {reader_errors[0]}"
            )
        stderr = "".join(stderr_tail).strip()
        if returncode not in {0, 1}:
            raise AtrexEvaluationError(
                _process_failure_message(returncode, stderr)
            )
        if not pointer_path.is_file():
            if returncode == 1 and "Traceback (most recent call last)" not in stderr:
                raise AtrexConfigError(
                    stderr or "run_eval rejected the SDK config"
                )
            raise AtrexEvaluationError(
                _process_failure_message(returncode, stderr)
            )
        return _load_eval_result(pointer_path, output_root)


def _stream_stderr(
    stream: BinaryIO,
    tail: deque[str],
    errors: list[OSError],
) -> None:
    decoder = getincrementaldecoder("utf-8")(errors="replace")
    pending = ""
    try:
        while chunk := stream.read(_SDK_STDERR_CHUNK_BYTES):
            text = decoder.decode(chunk)
            _mirror_stderr(text)
            pending = _append_stderr_tail(tail, pending, text)
        final_text = decoder.decode(b"", final=True)
        _mirror_stderr(final_text)
        pending = _append_stderr_tail(tail, pending, final_text)
    except OSError as error:
        errors.append(error)
    finally:
        if pending:
            tail.append(pending)


def _append_stderr_tail(
    tail: deque[str],
    pending: str,
    text: str,
) -> str:
    lines = (pending + text).splitlines(keepends=True)
    if lines and not lines[-1].endswith(("\n", "\r")):
        pending = lines.pop()
    else:
        pending = ""
    tail.extend(lines)
    return pending[-_SDK_STDERR_PARTIAL_LINE_CHARS:]


def _mirror_stderr(stderr: str) -> None:
    if not stderr:
        return
    try:
        sys.stderr.write(stderr)
        sys.stderr.flush()
    except (OSError, ValueError):
        pass


def _write_private_config(
    config: Mapping[str, object],
    config_path: Path,
) -> None:
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    try:
        descriptor = os.open(config_path, flags, 0o600)
        with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
            json.dump(
                config,
                handle,
                ensure_ascii=False,
                allow_nan=False,
            )
            handle.write("\n")
    except OSError as error:
        raise AtrexEvaluationError(
            f"failed to write temporary run_eval config: {error}"
        ) from error


def _start_process(command: list[str]) -> subprocess.Popen[bytes]:
    try:
        return subprocess.Popen(
            command,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.PIPE,
            bufsize=0,
            start_new_session=os.name == "posix",
        )
    except OSError as error:
        raise AtrexEvaluationError(
            f"failed to launch run_eval process: {error}"
        ) from error


def _stop_process(process: subprocess.Popen[bytes]) -> None:
    if process.poll() is not None:
        return
    try:
        if os.name == "posix":
            os.killpg(process.pid, signal.SIGINT)
        else:  # pragma: no cover - production workers run on Linux.
            process.terminate()
        process.wait(timeout=_SDK_PROCESS_SHUTDOWN_TIMEOUT_S)
        return
    except (OSError, subprocess.TimeoutExpired):
        pass
    try:
        if os.name == "posix":
            os.killpg(process.pid, signal.SIGTERM)
        else:  # pragma: no cover - production workers run on Linux.
            process.terminate()
        process.wait(timeout=_SDK_PROCESS_SHUTDOWN_TIMEOUT_S)
        return
    except (OSError, subprocess.TimeoutExpired):
        pass
    try:
        if os.name == "posix":
            os.killpg(process.pid, signal.SIGKILL)
        else:  # pragma: no cover - production workers run on Linux.
            process.kill()
        process.wait(timeout=_SDK_PROCESS_SHUTDOWN_TIMEOUT_S)
    except (OSError, subprocess.TimeoutExpired):
        return


def _process_failure_message(returncode: int, stderr: str) -> str:
    message = f"run_eval exited with code {returncode} without a valid result"
    return f"{message}: {stderr}" if stderr else message


def _load_eval_result(
    pointer_path: Path,
    output_root: Path,
) -> dict[str, object]:
    try:
        raw_pointer = pointer_path.read_text(encoding="utf-8").strip()
    except OSError as error:
        raise AtrexEvaluationError(
            f"failed to read run_eval result pointer: {error}"
        ) from error
    pointed_path = Path(raw_pointer)
    if not raw_pointer or not pointed_path.is_absolute():
        raise AtrexEvaluationError(
            "run_eval result pointer must contain an absolute path"
        )
    eval_result_path = pointed_path.resolve()
    if eval_result_path.name != "eval_result.json":
        raise AtrexEvaluationError(
            f"run_eval result pointer is not eval_result.json: {eval_result_path}"
        )
    try:
        eval_result_path.relative_to(output_root)
    except ValueError as error:
        raise AtrexEvaluationError(
            f"run_eval result path is outside output root: {eval_result_path}"
        ) from error
    try:
        payload = json.loads(eval_result_path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as error:
        raise AtrexEvaluationError(
            f"eval_result.json is not valid JSON: {error}"
        ) from error
    except OSError as error:
        raise AtrexEvaluationError(
            f"failed to read eval_result.json: {error}"
        ) from error
    if not isinstance(payload, dict):
        raise AtrexEvaluationError("eval_result.json must contain a JSON object")
    return payload


__all__ = [
    "AtrexConfigError",
    "AtrexEvaluationError",
    "AtrexSDKError",
    "evaluate",
]

"""Static cache validation must use the same floor and the matching device latency."""

from dataclasses import replace

import pytest

from atrex_bench.eval.roofline import RooflineHardware
from scripts import static_roofline_check as check


@pytest.mark.parametrize("work", [{}, {"bf16": 0}, {"bf16": 1}])
@pytest.mark.parametrize("q", [0, 1, 100])
def test_static_floor_agrees_with_work(work, q):
    hw = RooflineHardware("test", "test", "test", "test", {"bf16_tc": 1000}, 100, "")
    block = {"semantic_W_flops": work, "semantic_Q_read_bytes": q, "semantic_Q_write_bytes": 0}
    theory = check._compute_static_roofline(shape_id="x", shape_block=block, hw=hw)
    result = check._compute_static_roofline(
        shape_id="x", shape_block=block, hw=replace(hw, launch_overhead_s=0.02)
    )
    assert result.sol_time_s == (max(theory.sol_time_s, 0.02) if theory.sol_time_s else 0)


def test_production_latency_never_falls_back_to_another_device():
    meta = {
        "shapes": {
            "0": {
                "production_performance": {
                    "A": {"performance_us": 100},
                    "B": {"performance_us": 200},
                }
            }
        }
    }
    assert check._production_perf_us(meta, "0", "A") == 100
    assert check._production_perf_us(meta, "0", "B") == 200
    assert check._production_perf_us(meta, "0", "C") is None

"""Optional latency floors must agree across API and CLI calculation paths."""

import importlib.util
import json
from dataclasses import replace
from pathlib import Path

import pytest
import yaml

from atrex_bench.eval.roofline import (
    RooflineHardware,
    compute_roofline,
    compute_roofline_hybrid,
    load_hardware,
)

ROOT = Path(__file__).resolve().parents[1]
SPEC = RooflineHardware("test", "test", "test", "test", {"bf16_tc": 1000}, 100, "")


@pytest.mark.parametrize(
    "w,q,theory", [(1, 0, 0.001), (0, 1, 0.01), (1, 1, 0.01), (100, 1, 0.1), (0, 0, 0)]
)
@pytest.mark.parametrize("floor", [None, 0.02, 0.01])
@pytest.mark.parametrize("hybrid", [False, True])
def test_floor_preserves_theory_and_empty_work(w, q, theory, floor, hybrid):
    hw = replace(SPEC, launch_overhead_s=floor)
    result = (
        compute_roofline_hybrid({"bf16": w}, q, hw)
        if hybrid
        else compute_roofline(w, q, "bf16", hw)
    )
    expected = max(theory, floor or 0) if theory else 0
    assert result.sol_time_s == pytest.approx(expected)
    assert result.sol_time_ms == pytest.approx(expected * 1000)
    assert result.clamped_by_overhead == bool(floor and 0 < theory < floor)
    if w == 0:
        assert result.bottleneck == ("memory" if q else "no_compute")


@pytest.mark.parametrize(
    "value", [0, -1, True, False, "3e-6", float("nan"), float("inf"), -float("inf")]
)
def test_invalid_floor_rejected_in_file_and_direct_api(tmp_path, value):
    with pytest.raises(ValueError, match="launch_overhead_s"):
        replace(SPEC, launch_overhead_s=value)
    path = tmp_path / "test.yaml"
    path.write_text(
        yaml.safe_dump({"p_peak": SPEC.p_peak, "b_peak": {"hbm": 100}, "launch_overhead_s": value})
    )
    with pytest.raises(ValueError, match="launch_overhead_s"):
        load_hardware(path)


@pytest.mark.parametrize("config", [{}, {"launch_overhead_s": None}, {"launch_overhead_s": 0.02}])
def test_load_optional_floor(tmp_path, config):
    path = tmp_path / "test.yaml"
    path.write_text(yaml.safe_dump({"p_peak": SPEC.p_peak, "b_peak": {"hbm": 100}, **config}))
    assert load_hardware(path).launch_overhead_s == config.get("launch_overhead_s")


@pytest.mark.parametrize("work", [{}, {"bf16": 0}, {"bf16": 1}, {"bf16": 1, "fp16": 1}])
@pytest.mark.parametrize("q", [0, 1, 10])
def test_cli_shape_calculation_and_floor_flag(work, q):
    spec = importlib.util.spec_from_file_location("roofline_cli", ROOT / "scripts/roofline.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    hw = replace(SPEC, p_peak={"bf16_tc": 1000, "fp16_tc": 1000}, launch_overhead_s=0.02)
    result, *_ = module._shape_compute(
        shape_id="0",
        shape_block={
            "semantic_W_flops": work,
            "semantic_Q_read_bytes": q,
            "semantic_Q_write_bytes": 0,
        },
        hw=hw,
        explicit_dtype=None,
    )
    theory = max(sum(work.values()) / 1000, q / 100)
    assert result.sol_time_s == pytest.approx(max(theory, 0.02) if theory else 0)
    assert module._result_to_payload(result)["clamped_by_overhead"] == (0 < theory < 0.02)


def test_hybrid_sums_compute_before_applying_floor():
    hw = replace(SPEC, p_peak={"bf16_tc": 1000, "fp16_tc": 2000}, launch_overhead_s=0.02)
    result = compute_roofline_hybrid({"bf16": 10, "fp16": 40}, 1, hw)
    assert result.sol_time_s == pytest.approx(0.03)
    assert not result.clamped_by_overhead


def test_cli_no_write_does_not_modify_cache(tmp_path, monkeypatch, capsys):
    from scripts import roofline

    op = tmp_path / "op"
    op.mkdir()
    cached = {
        "shapes": {
            "0": {
                "semantic_W_flops": {},
                "semantic_Q_read_bytes": 1,
                "semantic_Q_write_bytes": 0,
                "SOL_time_ms": {"test": 99},
            }
        }
    }
    path = op / "roofline.json"
    path.write_text(json.dumps(cached))
    hardware = tmp_path / "test.yaml"
    hardware.write_text(
        yaml.safe_dump(
            {
                "hardware": {"name": "test"},
                "p_peak": SPEC.p_peak,
                "b_peak": {"hbm": 100},
                "launch_overhead_s": 0.02,
            }
        )
    )
    monkeypatch.setattr(
        "sys.argv",
        [
            "roofline",
            "--operator",
            str(op),
            "--hardware",
            str(hardware),
            "--no-write",
            "--format",
            "json",
        ],
    )
    assert roofline.main() == 0
    assert json.loads(path.read_text()) == cached
    assert '"clamped_by_overhead": true' in capsys.readouterr().out

"""Regression tests for metadata-owned correctness policies."""

import json

import pytest

from atrex_bench.eval.correctness import check_correctness, metadata_owns_correctness


def _write_problem(tmp_path, *, reference_body, candidate_body, contract, inputs):
    common = (
        "import torch\nclass Model(torch.nn.Module):\n"
        "    def forward(self, x, out, workspace):\n        "
    )
    reference = tmp_path / "reference.py"
    candidate = tmp_path / "candidate.py"
    reference.write_text(
        common
        + reference_body
        + "\n\ndef get_inputs():\n    return "
        + inputs
        + "\n\ndef get_init_inputs():\n    return []\n",
        encoding="utf-8",
    )
    candidate.write_text(common + candidate_body + "\n", encoding="utf-8")
    (tmp_path / "metadata.json").write_text(
        json.dumps({"benchmark_contract": contract}), encoding="utf-8"
    )
    return reference, candidate


def test_per_output_tolerances_override_global_policy(tmp_path):
    reference, candidate = _write_problem(
        tmp_path,
        reference_body="return (torch.ones_like(x), torch.ones_like(x))",
        candidate_body="return (torch.full_like(x, 1.05), torch.full_like(x, 1.005))",
        contract={
            "correctness_tolerances": {
                "output[0]": {"atol": 0.06, "rtol": 0.0},
                "output[1]": {"atol": 0.006, "rtol": 0.0},
            }
        },
        inputs="[torch.zeros(4), torch.zeros(4), torch.zeros(4)]",
    )

    result = check_correctness(
        reference,
        candidate,
        atol=0.0,
        rtol=0.0,
        max_rel_l2=0.0,
        device="cpu",
    )

    assert result.status == "passed", result.reason
    assert [diff.name for diff in result.cases[0].outputs] == ["output[0]", "output[1]"]
    assert metadata_owns_correctness(reference)


def test_mutation_tolerance_and_scratch_input(tmp_path):
    reference, candidate = _write_problem(
        tmp_path,
        reference_body="out.copy_(x + 1); workspace.fill_(1); return x",
        candidate_body="out.copy_(x + 1.05); workspace.fill_(2); return x",
        contract={
            "mutates_inputs": ["out"],
            "scratch_inputs": ["workspace"],
            "correctness_tolerances": {
                "output": {"atol": 0.0, "rtol": 0.0},
                "mutated_inputs.out": {"atol": 0.06, "rtol": 0.0},
            },
        },
        inputs="[torch.zeros(4), torch.zeros(4), torch.zeros(4)]",
    )

    result = check_correctness(reference, candidate, atol=0.0, rtol=0.0, device="cpu")

    assert result.status == "passed", result.reason
    assert result.cases[0].mutated_inputs[0].name == "input.out"
    assert all(diff.passed for diff in result.cases[0].unexpected_mutations)
    assert all(
        "workspace" not in diff.name for diff in result.cases[0].unexpected_mutations
    )


def test_default_output_policy_does_not_apply_to_mutated_inputs(tmp_path):
    reference, candidate = _write_problem(
        tmp_path,
        reference_body="out.fill_(1); return x",
        candidate_body="out.fill_(2); return x",
        contract={
            "mutates_inputs": ["out"],
            "correctness_tolerances": {
                "default": {
                    "atol": 0.0,
                    "rtol": 0.0,
                    "max_mismatch_fraction": 1.0,
                }
            },
        },
